-- V1__init.sql
-- Pick&Whip baseline schema (MySQL / Flyway)
-- NOTE:
--  - This file is an "init snapshot" that already includes the V1_1_0 refactor:
--    * custom_options.color_rgb_code is NULLable
--    * design_options.custom_id -> custom_option_id (with stable FK name)
--    * order_draft_items.custom_id removed
--    * order_items.custom_id -> custom_option_id, color_rgb_code NULLable (with stable FK name)
--    * report table includes status/answer/processed_at
--
-- After this version is merged, DO NOT edit this file again.
-- Any schema changes must be applied via a NEW migration (e.g. V2__*.sql).

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `bank_accounts` (
                                 `bank_account_id` bigint NOT NULL AUTO_INCREMENT,
                                 `account_holder` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
                                 `account_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
                                 `bank_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
                                 `is_primary` tinyint(1) DEFAULT '0',
                                 `shop_id` bigint DEFAULT NULL,
                                 PRIMARY KEY (`bank_account_id`),
                                 KEY `FKt6t7oiuxdwfcu798ik0kmkcb2` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `chat_messages` (
                                 `chat_id` bigint NOT NULL AUTO_INCREMENT,
                                 `created_at` datetime(6) NOT NULL,
                                 `updated_at` datetime(6) NOT NULL,
                                 `is_read` bit(1) NOT NULL,
                                 `message_image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                                 `message_text` text COLLATE utf8mb4_unicode_ci,
                                 `message_type` enum('IMAGE','TEXT') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                                 `room_id` bigint DEFAULT NULL,
                                 `sender_id` bigint DEFAULT NULL,
                                 PRIMARY KEY (`chat_id`),
                                 KEY `FKhalwepod3944695ji0suwoqb9` (`room_id`),
                                 KEY `FKgiqeap8ays4lf684x7m0r2729` (`sender_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `chat_rooms` (
                              `chat_room_id` bigint NOT NULL AUTO_INCREMENT,
                              `created_at` datetime(6) NOT NULL,
                              `updated_at` datetime(6) NOT NULL,
                              `last_message_id` bigint DEFAULT NULL,
                              `customer_id` bigint DEFAULT NULL,
                              `shop_id` bigint DEFAULT NULL,
                              PRIMARY KEY (`chat_room_id`),
                              KEY `FK42l1eff8qlbln1331stm3ml2h` (`customer_id`),
                              KEY `FKtqhifsbloj4e5rlyobaljrx3f` (`shop_id`)
