                          `lettering_line_count` enum('ONE_LINE','THREE_LINE','TWO_LINE') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                          `lettering_text` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
