                          `payment_status` enum('CANCELLED','PAID','WAITING') COLLATE utf8mb4_unicode_ci NOT NULL,
                          `pickup_datetime` datetime(6) NOT NULL,
                          `reference_image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                          `rejection_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                          `status` enum('COMPLETED','CONFIRM_WAIT','IMPOSSIBLE','MAKING','PICKUP_WAIT','PROD_CONFIRM') COLLATE utf8mb4_unicode_ci NOT NULL,
                          `total_price` int NOT NULL,
                          `design_id` bigint NOT NULL,
                          `shop_id` bigint NOT NULL,
                          `shop_cake_size_id` bigint NOT NULL,
                          `user_id` bigint NOT NULL,
                          PRIMARY KEY (`id`),
