CREATE TABLE `orders_drafts` (
                                 `id` bigint NOT NULL AUTO_INCREMENT,
                                 `created_at` datetime(6) NOT NULL,
                                 `updated_at` datetime(6) NOT NULL,
                                 `additional_request` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                                 `lettering_alignment` enum('CENTER','CURVE_UP','CURVE_UP_DOWN') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                                 `lettering_line_count` enum('ONE_LINE','THREE_LINE','TWO_LINE') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                                 `lettering_text` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
