CREATE TABLE `payments` (
                            `payment_id` bigint NOT NULL AUTO_INCREMENT,
                            `approved_at` datetime(6) DEFAULT NULL,
                            `discount_amount` bigint DEFAULT NULL,
                            `payment_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                            `payment_method` enum('CARD','SIMPLE_PAY','TRANSFER','VIRTUAL_ACCOUNT') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                            `receipt_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                            `requested_at` datetime(6) DEFAULT NULL,
                            `status` enum('ABORTED','CANCELED','DONE','PARTIAL_CANCELED','READY') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                            `total_amount` bigint NOT NULL,
                            `order_id` bigint DEFAULT NULL,
                            PRIMARY KEY (`payment_id`),
                            UNIQUE KEY `UK35yqdahtiysne6iij9ske72bj` (`payment_key`),
                            UNIQUE KEY `UK8vo36cen604as7etdfwmyjsxt` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `report` (
                          `report_id` bigint NOT NULL AUTO_INCREMENT,
                          `created_at` datetime(6) NOT NULL,
                          `updated_at` datetime(6) NOT NULL,
                          `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
                          `reason_type` enum('COPYRIGHT_INFRINGEMENT','FALSE_INFORMATION','FRAUD_SUSPECTED','INAPPROPRIATE_CONTENT','OTHER','SPAM_OR_AD') COLLATE utf8mb4_unicode_ci NOT NULL,
                          `target_id` bigint DEFAULT NULL,
                          `target_type` enum('CHAT','REVIEW','SHOP') COLLATE utf8mb4_unicode_ci NOT NULL,
                          `reporter_id` bigint DEFAULT NULL,
                          `status` enum('PENDING','COMPLETED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
                          `answer` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                          `processed_at` datetime(6) DEFAULT NULL,
                          PRIMARY KEY (`report_id`),
                          KEY `FKqbhdxqd3ly7fkhly5nrl2j93k` (`reporter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `review` (
                          `id` bigint NOT NULL AUTO_INCREMENT,
                          `created_at` datetime(6) NOT NULL,
                          `updated_at` datetime(6) NOT NULL,
                          `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
                          `deleted_at` datetime(6) DEFAULT NULL,
                          `rating` int NOT NULL,
                          PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `review_image` (
                                `id` bigint NOT NULL AUTO_INCREMENT,
                                `created_at` datetime(6) NOT NULL,
                                `updated_at` datetime(6) NOT NULL,
                                `deleted_at` datetime(6) DEFAULT NULL,
                                `s3_key` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
                                `sort_order` int NOT NULL,
                                `review_id` bigint NOT NULL,
                                `active_sort_order` int GENERATED ALWAYS AS (
                                    CASE WHEN (`deleted_at` IS NULL) THEN `sort_order` ELSE NULL END
                                    ) STORED,
                                PRIMARY KEY (`id`),
                                UNIQUE KEY `uk_review_image_review_active_order` (`review_id`,`active_sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `review_keyword` (
